def transform(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    sr={i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg}
    sc={j for j in range(w) if len({g[i][j] for i in range(h)})==1 and g[0][j]!=bg}
    def groups(idx):
        out=[];cur=[]
        for i in idx:
            if cur and i==cur[-1]+1: cur.append(i)
            else:
                if cur: out.append(cur)
                cur=[i]
        if cur: out.append(cur)
        return out
    rgs=groups([i for i in range(h) if i not in sr]); cgs=groups([j for j in range(w) if j not in sc])
    pat=None
    for rg in rgs:
        for cg in cgs:
            if any(g[i][j]!=bg for i in rg for j in cg): pat=(rg,cg)
    rg,cg=pat
    P=[[g[i][j] for j in cg] for i in rg]
    ph,pw=len(P),len(P[0])
    out=[row[:] for row in g]
    for r2 in rgs:
        for c2 in cgs:
            for a,i in enumerate(r2):
                for b,j in enumerate(c2):
                    out[i][j]=P[a%ph][b%pw]
    return out
